<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides compensation review item behavior within the WorkIntel application. */ class CompensationReviewItem extends Model{protected $fillable=['workspace_id','cycle_id','member_id','current_amount','proposed_amount','currency','current_title','proposed_title','status','justification','reviewed_by','reviewed_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['current_amount'=>'decimal:2','proposed_amount'=>'decimal:2','reviewed_at'=>'datetime'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}}
